import sys
import time
from concurrent.futures import Future, ThreadPoolExecutor

import pytest


class Bad(Exception):
    def __init__(self, n: int) -> None:
        self.n = n


def check(x: int) -> int:
    if x % 2 == 1:
        raise Bad(x)
    return x


def all_even(xs: list[int]) -> list[int]:
    """Run check on every element of xs in parallel using a thread pool.

    Returns the checked values in input order. If any elements are bad,
    raises the Bad for the lowest-index bad element, regardless of which
    thread finishes first.
    """
    workers = min(32, max(1, len(xs)))
    with ThreadPoolExecutor(max_workers=workers) as pool:
        futures: list[Future[int]] = [pool.submit(check, x) for x in xs]
        results: list[int] = []
        try:
            # Collect in index order: the first future that raises is the
            # lowest-index bad element, independent of completion order.
            for fut in futures:
                results.append(fut.result())
        except Bad:
            for fut in futures:
                fut.cancel()
            raise
    return results


def test_all_even_returns_in_order() -> None:
    assert all_even([4, 2, 8, 0, 6]) == [4, 2, 8, 0, 6]


def test_all_even_empty() -> None:
    assert all_even([]) == []


def test_single_bad() -> None:
    with pytest.raises(Bad) as ei:
        all_even([2, 4, 5, 6])
    assert ei.value.n == 5


def test_lowest_index_not_lowest_value() -> None:
    with pytest.raises(Bad) as ei:
        all_even([10, 7, 3, 9])
    assert ei.value.n == 7


def test_bad_first_and_last() -> None:
    with pytest.raises(Bad) as ei:
        all_even([1, 2, 3])
    assert ei.value.n == 1


def test_lowest_index_wins_even_if_it_finishes_last(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    original = check

    def slow_check(x: int) -> int:
        if x == 7:
            time.sleep(0.2)
        return original(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    with pytest.raises(Bad) as ei:
        all_even([2, 7, 4, 3, 5])
    assert ei.value.n == 7


def test_results_ordered_despite_finish_order(
    monkeypatch: pytest.MonkeyPatch,
) -> None:
    original = check

    def slow_check(x: int) -> int:
        if x == 2:
            time.sleep(0.2)
        return original(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    assert all_even([2, 4, 6, 8]) == [2, 4, 6, 8]


def test_runs_in_parallel(monkeypatch: pytest.MonkeyPatch) -> None:
    original = check

    def slow_check(x: int) -> int:
        time.sleep(0.2)
        return original(x)

    monkeypatch.setattr(sys.modules[__name__], "check", slow_check)
    start = time.monotonic()
    assert all_even([0, 2, 4, 6]) == [0, 2, 4, 6]
    assert time.monotonic() - start < 0.7
